<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>KejaLink API documentation</title>
  <link rel="stylesheet" href="/swagger-ui-assets/swagger-ui.css">
  <style>
    body { margin: 0; background: #fafafa; }
    .topbar-custom {
      display: flex; gap: 8px; align-items: center; padding: 12px 20px;
      background: #1b1b1b; color: #fff; font-family: sans-serif;
    }
    .topbar-custom strong { margin-right: 12px; }
    .topbar-custom input {
      flex: 1; min-width: 0; padding: 8px 10px; border-radius: 4px; border: 1px solid #555;
      background: #2b2b2b; color: #fff; font-size: 14px;
    }
    .topbar-custom button {
      padding: 8px 16px; border: 0; border-radius: 4px; cursor: pointer;
      background: #49cc90; color: #000; font-weight: 600;
    }
    #notice { display: none; padding: 10px 20px; background: #fff3cd; color: #664d03;
      font-family: sans-serif; font-size: 14px; }
    @media (max-width: 600px) {
      .topbar-custom { flex-wrap: wrap; }
      .topbar-custom strong { width: 100%; }
    }
  </style>
</head>
<body>
  <div class="topbar-custom">
    <strong>KejaLink API</strong>
    <input id="specUrl" value="/api-docs.json" aria-label="OpenAPI document URL">
    <button id="loadSpec" type="button">Load</button>
  </div>
  <div id="notice" role="alert"></div>
  <div id="swagger-ui"></div>

  <script src="/swagger-ui-assets/swagger-ui-bundle.js"></script>
  <script>
    const notice = document.getElementById('notice');

    function render(url) {
      window.ui = SwaggerUIBundle({
        url,
        dom_id: '#swagger-ui',
        deepLinking: true,
        persistAuthorization: true,
        tryItOutEnabled: true,
        requestInterceptor(request) {
          if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method.toUpperCase())) {
            request.headers['X-KejaLink'] = '1';
          }
          return request;
        },
      });
    }

    async function loadSpec() {
      const url = document.getElementById('specUrl').value.trim();
      if (!url) {
        notice.textContent = 'Enter the URL of an OpenAPI document.';
        notice.style.display = 'block';
        return;
      }

      try {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const spec = await response.json();
        if (!spec.openapi && !spec.swagger) throw new Error('The response is not an OpenAPI document.');
        notice.style.display = 'none';
        render(url);
      } catch (error) {
        notice.textContent = `Could not load ${url}: ${error.message}. Make sure the API server is running and the URL points to an OpenAPI document.`;
        notice.style.display = 'block';
      }
    }

    document.getElementById('loadSpec').addEventListener('click', loadSpec);
    loadSpec();
  </script>
</body>
</html>
